import React, { useState } from "react";

function Home() {

  const [cartCount, setCartCount] = useState(0);

  const addToCart = () => {
    setCartCount(cartCount + 1);
  };

  const products = [
    {
      _id: 1,
      name: "Nike Air Max",
      price: 4999,
      image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff"
    },
    {
      _id: 2,
      name: "Oversized T-Shirt",
      price: 1299,
      image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab"
    },
    {
      _id: 3,
      name: "Wireless Headphones",
      price: 2999,
      image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e"
    },
    {
      _id: 4,
      name: "Smart Watch",
      price: 5999,
      image: "https://images.unsplash.com/photo-1517430816045-df4b7de11d1d"
    },
    {
      _id: 5,
      name: "Gaming Mouse",
      price: 1499,
      image: "https://images.unsplash.com/photo-1527814050087-3793815479db"
    },
    {
      _id: 6,
      name: "Backpack",
      price: 1999,
      image: "https://images.unsplash.com/photo-1581605405669-fcdf81165afa"
    },
    {
      _id: 7,
      name: "Sneakers",
      price: 3499,
      image: "https://images.unsplash.com/photo-1549298916-b41d501d3772"
    },
    {
      _id: 8,
      name: "Sunglasses",
      price: 899,
      image: "https://images.unsplash.com/photo-1511499767150-a48a237f0083"
    }
  ];

  return (
    <div
      style={{
        background: "#f1f5f9",
        minHeight: "100vh",
        fontFamily: "Arial"
      }}
    >

      {/* Navbar */}

      <div
        style={{
          background: "#0f172a",
          color: "white",
          padding: "18px 50px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          position: "sticky",
          top: "0",
          zIndex: "1000",
          boxShadow: "0 4px 10px rgba(0,0,0,0.3)"
        }}
      >

        <h1
          style={{
            fontSize: "32px"
          }}
        >
          🛒 ShopEasy
        </h1>

        <div
          style={{
            display: "flex",
            gap: "30px",
            fontSize: "18px",
            alignItems: "center"
          }}
        >
          <span style={{cursor:"pointer"}}>Home</span>
          <span style={{cursor:"pointer"}}>Products</span>

          <div
            style={{
              background: "#2563eb",
              padding: "10px 18px",
              borderRadius: "8px",
              fontWeight: "bold"
            }}
          >
            Cart ({cartCount})
          </div>

        </div>

      </div>

      {/* Hero Section */}

      <div
        style={{
          background:
            "linear-gradient(to right, #0f172a, #1e293b)",
          color: "white",
          padding: "90px 40px",
          textAlign: "center"
        }}
      >

        <h1
          style={{
            fontSize: "65px",
            marginBottom: "20px"
          }}
        >
          Welcome To ShopEasy
        </h1>

        <p
          style={{
            fontSize: "22px",
            color: "#cbd5e1",
            maxWidth: "700px",
            margin: "auto",
            lineHeight: "35px"
          }}
        >
          Discover premium fashion, electronics,
          gadgets and accessories at unbeatable prices.
        </p>

        <button
          style={{
            marginTop: "35px",
            padding: "16px 35px",
            background: "#2563eb",
            color: "white",
            border: "none",
            borderRadius: "10px",
            fontSize: "18px",
            cursor: "pointer",
            fontWeight: "bold",
            boxShadow: "0 4px 12px rgba(37,99,235,0.5)"
          }}
        >
          Shop Now
        </button>

      </div>

      {/* Features */}

      <div
        style={{
          display: "flex",
          justifyContent: "center",
          gap: "30px",
          padding: "40px",
          flexWrap: "wrap"
        }}
      >

        <div
          style={{
            background: "white",
            padding: "25px",
            width: "250px",
            borderRadius: "15px",
            textAlign: "center",
            boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
          }}
        >
          <h2>🚚 Free Delivery</h2>
          <p>Fast delivery across India.</p>
        </div>

        <div
          style={{
            background: "white",
            padding: "25px",
            width: "250px",
            borderRadius: "15px",
            textAlign: "center",
            boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
          }}
        >
          <h2>💳 Secure Payment</h2>
          <p>100% secure payment gateway.</p>
        </div>

        <div
          style={{
            background: "white",
            padding: "25px",
            width: "250px",
            borderRadius: "15px",
            textAlign: "center",
            boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
          }}
        >
          <h2>⭐ Top Quality</h2>
          <p>Premium quality products.</p>
        </div>

      </div>

      {/* Products */}

      <div
        style={{
          padding: "40px"
        }}
      >

        <h2
          style={{
            textAlign: "center",
            fontSize: "45px",
            marginBottom: "50px",
            color: "#0f172a"
          }}
        >
          Featured Products
        </h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns:
              "repeat(auto-fit,minmax(280px,1fr))",
            gap: "35px"
          }}
        >

          {products.map((p) => (

            <div
              key={p._id}
              style={{
                background: "white",
                borderRadius: "18px",
                overflow: "hidden",
                boxShadow: "0 6px 16px rgba(0,0,0,0.15)",
                transition: "0.3s"
              }}
            >

              <img
                src={p.image}
                alt={p.name}
                style={{
                  width: "100%",
                  height: "260px",
                  objectFit: "cover"
                }}
              />

              <div
                style={{
                  padding: "20px"
                }}
              >

                <h2
                  style={{
                    fontSize: "24px",
                    marginBottom: "12px",
                    color: "#111827"
                  }}
                >
                  {p.name}
                </h2>

                <p
                  style={{
                    fontSize: "22px",
                    color: "#16a34a",
                    fontWeight: "bold"
                  }}
                >
                  ₹{p.price}
                </p>

                <button
                  onClick={addToCart}
                  style={{
                    marginTop: "18px",
                    width: "100%",
                    padding: "14px",
                    background: "#111827",
                    color: "white",
                    border: "none",
                    borderRadius: "10px",
                    fontSize: "17px",
                    cursor: "pointer",
                    fontWeight: "bold"
                  }}
                >
                  Add To Cart
                </button>

              </div>

            </div>

          ))}

        </div>

      </div>

      {/* Footer */}

      <div
        style={{
          background: "#0f172a",
          color: "white",
          textAlign: "center",
          padding: "30px",
          marginTop: "60px"
        }}
      >

        <h2>🛒 ShopEasy</h2>

        <p
          style={{
            color: "#cbd5e1"
          }}
        >
          MERN Stack E-Commerce Project
        </p>

        <p
          style={{
            marginTop: "10px",
            color: "#94a3b8"
          }}
        >
          © 2026 All Rights Reserved
        </p>

      </div>

    </div>
  );
}

export default Home;
